// Plain data types behind the generated animal-avatar data (avatar_data.dart).
//
// Why separate: the data file is generated by tool/art/gen_avatars.js from the
// design source of truth; these hand-written types stay stable while it is
// regenerated.

/// Which idle animation a part takes part in (design board A §9).
enum AvatarAnim {
  /// Static.
  none,

  /// Eyes: scaleY 1 → .1 → 1 every 4.2 s.
  blink,

  /// Left ear: ±9° wiggle at its base every 5 s.
  earLeft,

  /// Right ear: the same wiggle, 1.4 s later.
  earRight,
}

/// One vector layer of an avatar in a 48 × 48 box.
class AvatarPart {
  const AvatarPart(
    this.d, {
    this.fill,
    this.stroke,
    this.strokeWidth = 0,
    this.anim = AvatarAnim.none,
    this.ox = 24,
    this.oy = 24,
  });

  /// SVG path data.
  final String d;

  /// ARGB fill, or null for none.
  final int? fill;

  /// ARGB stroke, or null for none.
  final int? stroke;
  final double strokeWidth;
  final AvatarAnim anim;

  /// Transform origin (in the 48-box) for [anim].
  final double ox;
  final double oy;
}

/// A whole animal: flat background + ordered parts.
class AvatarArt {
  const AvatarArt({required this.background, required this.parts});

  /// ARGB of the square behind the animal.
  final int background;
  final List<AvatarPart> parts;
}
